def bh(hyp, q):
    """hyp = [(p, name), ...]; returns (kmax, survivors, smallest_p, name)."""
    hyp = sorted(hyp)
    m = len(hyp)
    kmax = 0
    for i, (p, _n) in enumerate(hyp, start=1):
        if p <= (i / m) * q:
            kmax = i
    return kmax, [n for _p, n in hyp[:kmax]], hyp[0][0], hyp[0][1]


